def rule(t, A):
    """the camel flipped to the trade side on a single hump (|camStk| == 1) whose amplitude is under 2 pips."""
    k = t["k"]
    if abs(t["camStk"]) != 1:
        return False
    H = A.humps_known(k)
    if not len(H):
        return False
    b0, v0, bh, vh, b1, v1, tr, kn = H[-1]
    return (vh - min(v0, v1)) < 2 * A.PIP

